ICON_BOX = 44
ICON_PAD = 7
CORNER   = 8
GAP      = 14
SVG_W    = 900
SVG_H    = 120
ROW1_Y   = 10
ROW2_Y   = 62
FADE_W   = 64
BG       = "#0d1117"


def render_row(icons, y):
    draw = ICON_BOX - ICON_PAD * 2
    parts = []
    x = 0
    for _ in range(2):
        for label, bg, fg, path_d in icons:
            parts.append(
                f'<rect x="{x}" y="{y}" width="{ICON_BOX}" height="{ICON_BOX}"'
                f' rx="{CORNER}" fill="{bg}"/>'
            )
            scale = draw / 24
            tx = x + ICON_PAD
            ty = y + ICON_PAD
            parts.append(
                f'<g transform="translate({tx:.1f},{ty:.1f}) scale({scale:.5f})">'
                f'<path d="{path_d}" fill="{fg}"/></g>'
            )
            x += ICON_BOX + GAP
        x += GAP
    return parts, x // 2 - GAP


def generate():
    el1, w1 = render_row(ROW1, ROW1_Y)
    el2, w2 = render_row(ROW2, ROW2_Y)

    dur1 = round(w1 / 55, 1)
    dur2 = round(w2 / 55, 1)

    lines = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{SVG_W}" height="{SVG_H}" viewBox="0 0 {SVG_W} {SVG_H}">',
        f'<rect width="{SVG_W}" height="{SVG_H}" fill="{BG}"/>',
        "<defs>",
        f'<clipPath id="clip"><rect width="{SVG_W}" height="{SVG_H}"/></clipPath>',
        f'<linearGradient id="gl" x1="0" x2="1"><stop offset="0%" stop-color="{BG}"/><stop offset="100%" stop-color="{BG}" stop-opacity="0"/></linearGradient>',
        f'<linearGradient id="gr" x1="1" x2="0"><stop offset="0%" stop-color="{BG}"/><stop offset="100%" stop-color="{BG}" stop-opacity="0"/></linearGradient>',
        "</defs>",
        "<style>",
        f".r1{{animation:m1 {dur1}s linear infinite;}}",
        f".r2{{animation:m2 {dur2}s linear infinite;}}",
        f"@keyframes m1{{from{{transform:translateX(0)}}to{{transform:translateX(-{w1+GAP}px)}}}}",
        f"@keyframes m2{{from{{transform:translateX(-{w2+GAP}px)}}to{{transform:translateX(0)}}}}",
        "</style>",
        '<g clip-path="url(#clip)">',
        '<g class="r1">',
    ]
    lines.extend(el1)
    lines += ["</g>", '<g class="r2">']
    lines.extend(el2)
    lines += ["</g>", "</g>",
              f'<rect width="{FADE_W}" height="{SVG_H}" fill="url(#gl)"/>',
              f'<rect x="{SVG_W-FADE_W}" width="{FADE_W}" height="{SVG_H}" fill="url(#gr)"/>',
              "</svg>"]
    return "\n".join(lines)


if __name__ == "__main__":
    out = sys.argv[1] if len(sys.argv) > 1 else "marquee.svg"
    os.makedirs(os.path.dirname(out) if os.path.dirname(out) else ".", exist_ok=True)
    svg = generate()
    with open(out, "w", encoding="utf-8") as f:
        f.write(svg)
    print(f"Written: {out}  ({len(svg):,} bytes)")
